#include <iostream>
#include <queue>
#include <algorithm>
using namespace std;

const int MAXN = 25;
const int MAXV = 505;
const int MAXE = 400005;
const int INF = 1000000007;
const int SRC = 501, SNK = 502;

char A[MAXN][MAXN], B[MAXN][MAXN];
int Zdist[MAXN][MAXN];
int pairDist[MAXN][MAXN][MAXN][MAXN];

int head[MAXV], toEdge[MAXE], nxtEdge[MAXE], capEdge[MAXE], flowEdge[MAXE];
int edgeCnt;
int parentEdge[MAXV], used[MAXV], dep[MAXV];
int answer;
int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

inline void addEdge(int u, int v, int cap) {
    toEdge[edgeCnt] = v;
    capEdge[edgeCnt] = cap;
    flowEdge[edgeCnt] = 0;
    nxtEdge[edgeCnt] = head[u];
    head[u] = edgeCnt++;
    toEdge[edgeCnt] = u;
    capEdge[edgeCnt] = 0;
    flowEdge[edgeCnt] = 0;
    nxtEdge[edgeCnt] = head[v];
    head[v] = edgeCnt++;
}

inline bool bfsLevel() {
    queue<int> qu;
    for (int i = 0; i <= SNK; ++i) used[i] = dep[i] = 0;
    qu.push(SRC);
    used[SRC] = 1;
    dep[SRC] = 1;
    while (!qu.empty()) {
        int x = qu.front(); qu.pop();
        for (int i = head[x]; i != -1; i = nxtEdge[i]) {
            int y = toEdge[i];
            if (!used[y] && flowEdge[i] < capEdge[i]) {
                parentEdge[y] = i;
                used[y] = 1;
                dep[y] = dep[x] + 1;
                qu.push(y);
                if (y == SNK) return true;
            }
        }
    }
    return false;
}

inline int sendFlow(int x, int now) {
    if (x == SNK || !now) return now;
    int rem = now;
    for (int i = head[x]; i != -1; i = nxtEdge[i]) {
        int y = toEdge[i];
        if (capEdge[i] > flowEdge[i] && dep[y] == dep[x] + 1) {
            int pushed = sendFlow(y, min(rem, capEdge[i] - flowEdge[i]));
            if (!pushed) dep[y] = 0;
            flowEdge[i] += pushed;
            flowEdge[i ^ 1] -= pushed;
            rem -= pushed;
            if (rem == 0) break;
        }
    }
    return now - rem;
}

inline void dinic() {
    while (bfsLevel()) answer += sendFlow(SRC, INF);
}

int main() {
    int n, timeLimit;
    cin >> n >> timeLimit;
    for (int i = 0; i < MAXV; ++i) head[i] = -1;
    edgeCnt = 0;

    queue<pair<int, int>> q;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            Zdist[i][j] = 10000;
            cin >> A[i][j];
            if (A[i][j] == 'Z') {
                q.push({i, j});
                Zdist[i][j] = 0;
            }
            if (A[i][j] <= '9')
                addEdge(SRC, (i - 1) * n + j, A[i][j] - '0');
        }
    }

    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx > 0 && ny > 0 && nx <= n && ny <= n && A[nx][ny] <= '9' &&
                Zdist[nx][ny] > Zdist[x][y] + 1) {
                Zdist[nx][ny] = Zdist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (A[i][j] > '9') continue;
            for (int k = 1; k <= n; ++k)
                for (int l = 1; l <= n; ++l)
                    pairDist[i][j][k][l] = 10000;
            q.push({i, j});
            pairDist[i][j][i][j] = 0;
            while (!q.empty()) {
                int x = q.front().first, y = q.front().second;
                q.pop();
                for (int f = 0; f < 4; ++f) {
                    int nx = x + dx[f], ny = y + dy[f];
                    if (nx > 0 && ny > 0 && nx <= n && ny <= n && A[nx][ny] <= '9' &&
                        pairDist[i][j][nx][ny] > pairDist[i][j][x][y] + 1 &&
                        pairDist[i][j][x][y] < Zdist[x][y]) {
                        pairDist[i][j][nx][ny] = pairDist[i][j][x][y] + 1;
                        q.push({nx, ny});
                    }
                }
            }
            for (int k = 1; k <= n; ++k)
                for (int l = 1; l <= n; ++l)
                    if (pairDist[i][j][k][l] <= min(Zdist[k][l], timeLimit))
                        addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cin >> B[i][j];
            if (B[i][j] <= '9')
                addEdge((i - 1) * n + j + 100, SNK, B[i][j] - '0');
        }
    }

    dinic();
    cout << answer;
    return 0;
}
